  const b = (k: string, d: boolean, bare: boolean): boolean => { const c = kid(t, k); if (!c) return d; if (c.length < 2) return bare; const v = String(c[1]); return v === "yes" || v === "true" ? true : v === "no" || v === "false" ? false : d; };
